 c=0
 while c<w:
  if g[r][c]==4:
   a=c
   while c<w and g[r][c]==4:c+=1
   if a>0 and c<w and g[r][a-1]==9 and g[r][c]==9:
    for x in range(a,c):out[r][x]=2
  else:c+=1
for c in range(w):
 r=0
 while r<h:
